function capacityBytes(w,h){
  if(!isFinite(w)||!isFinite(h)||w<=0||h<=0) return 0;
  return Math.floor(w*h*3/8);
}
function utf8Encode(str){ return unescape(encodeURIComponent(String(str==null?'':str))); }
function utf8Decode(bytes){
  try{ return decodeURIComponent(escape(bytes)); }
  catch(e){ return bytes; }
}
function encodeLsb(data, text){
  if(!data||!data.length) return {error:'缺少像素数据'};
  var bytes=utf8Encode(text);
  var needed=6+bytes.length;
  var cap=Math.floor(data.length/4*3/8);
  if(needed>cap) return {error:'容量不足：需要 '+needed+' 字节，仅可容纳 '+cap+' 字节（请缩短文本或换更大图片）', needed:needed, capacity:cap};
  var bits=[];
  bits.push(0x57,0x42);
  var len=bytes.length;
  bits.push((len>>>24)&255,(len>>>16)&255,(len>>>8)&255,len&255);
  for(var i=0;i<bytes.length;i++) bits.push(bytes.charCodeAt(i));
  var out=new Uint8Array(data.length);
  for(var j=0;j<data.length;j++) out[j]=data[j];
  var bitIdx=0;
  for(var k=0;k<bits.length;k++){
    for(var b=7;b>=0;b--){
      var bit=(bits[k]>>b)&1;
      var pix=Math.floor(bitIdx/3), ch=bitIdx%3;
      var idx=pix*4+ch;
      out[idx]=(out[idx]&0xFE)|bit;
      bitIdx++;
    }
  }
  var changed=0;
  for(var n=0;n<data.length;n++) if(out[n]!==data[n]) changed++;
  return {data:out, bytesUsed:bits.length, capacity:cap, changedBytes:changed, pixelsUsed:Math.ceil(bits.length*8/3)};
}
function decodeLsb(data){
  if(!data||!data.length) return {error:'缺少像素数据'};
  var totalBits=Math.floor(data.length/4*3);
  if(totalBits<48) return {ok:false, error:'图像过小，无法容纳隐写头部'};
  function readBit(i){ var pix=Math.floor(i/3), ch=i%3; return data[pix*4+ch]&1; }
  var m0=0, m1=0;
  for(var a=0;a<8;a++){ m0=(m0<<1)|readBit(a); m1=(m1<<1)|readBit(8+a); }
  if(m0!==0x57||m1!==0x42) return {ok:false, error:'未检测到隐写数据（magic 不匹配）'};
  var len=0;
  for(var a2=16;a2<48;a2++){ len=(len<<1)|readBit(a2); }
  var cap=Math.floor(data.length/4*3/8);
  if(len<0||len>cap-6) return {ok:false, error:'长度头部异常：'+len+'（图片可能被缩放或有损压缩损坏）'};
  var bytes='';
  for(var k=0;k<len;k++){
    var v=0;
    for(var b2=0;b2<8;b2++){ v=(v<<1)|readBit(48+k*8+b2); }
    bytes+=String.fromCharCode(v);
  }
  return {ok:true, text:utf8Decode(bytes), bytesUsed:6+len, capacity:cap};
}
var EXPORTS={capacityBytes:capacityBytes, utf8Encode:utf8Encode, utf8Decode:utf8Decode, encodeLsb:encodeLsb, decodeLsb:decodeLsb};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.StegoForgePure = EXPORTS; }
